"""Etapa 4a: calendário de risco (cálculo + tela). Rode uma vez, na raiz do projeto, e apague."""
import subprocess, sys
from pathlib import Path

if not Path("etl/historico/infodengue.py").exists():
    sys.exit("Rode na raiz do projeto, depois da etapa 3d.")
if Path("etl/derivados/calendario.py").exists():
    sys.exit("A etapa 4a já foi aplicada.")
pendentes = [l for l in subprocess.run(["git", "status", "--porcelain"], capture_output=True, text=True).stdout.splitlines() if not l.endswith("aplicar_4a.py")]
if pendentes:
    sys.exit("Há mudanças não commitadas. Faça commit ou stash antes.")

NOVOS = {
    'etl/derivados/__init__.py': '"""Tabelas derivadas: calculadas a partir de outras silvers, não de uma fonte externa.\n\nRodam à mão quando os dados de origem mudam (a Defesa Civil é anual).\nLeem o MongoDB direto pelo destino; por isso valem só para o destino Mongo.\n"""\n',
    'etl/derivados/calendario.py': '"""Calendário de risco: em que época do ano cada distrito mais precisa de equipe (etapa 4a).\n\nA partir dos atendimentos REATIVOS da Defesa Civil (2014-2024), por distrito e dia:\n  - média de atendimentos por dia em cada mês, e quanto isso é acima da média do distrito (índice)\n  - período crítico: os meses seguidos com índice >= 1,5 (50% acima da média do próprio distrito)\n  - semana de pico: a semana do ano com mais atendimentos (média móvel de 3 semanas)\n  - variação entre os anos: em cada mês, o ano mais calmo e o mais intenso\n\n  gold  gold.calendario_risco_mes        distrito x mês\n  gold  gold.calendario_risco_distrito   resumo por distrito (código 0 = Recife inteiro)\n\nUso:\n    python -m etl.derivados.calendario\n"""\n\nfrom collections import defaultdict\nfrom datetime import date, datetime, timedelta, timezone\n\nfrom dominio.distritos import nome_distrito\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\n\nINICIO, FIM = date(2014, 1, 1), date(2024, 12, 31)\nLIMIAR_CRITICO = 1.5\nMESES = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho",\n         "agosto", "setembro", "outubro", "novembro", "dezembro"]\nCIDADE = 0\n\n\ndef _semana(d):\n    """Semana do ano de 0 a 51 (a 53ª, de 1 ou 2 dias, entra na 52ª)."""\n    return min((d.timetuple().tm_yday - 1) // 7, 51)\n\n\ndef periodo_critico(indices):\n    """A maior sequência de meses seguidos (dez -> jan conta) com índice >= limiar. [] se nenhum."""\n    melhor, atual = [], []\n    for m in list(range(12)) * 2:\n        if indices[m] >= LIMIAR_CRITICO:\n            atual.append(m)\n            if len(atual) > len(melhor) and len(atual) <= 12:\n                melhor = list(atual)\n        else:\n            atual = []\n    return [m + 1 for m in melhor]\n\n\ndef texto_periodo(meses):\n    if not meses:\n        return "sem período marcadamente acima da média"\n    if len(meses) == 1:\n        return MESES[meses[0] - 1]\n    return f"{MESES[meses[0] - 1]} a {MESES[meses[-1] - 1]}"\n\n\ndef calcular(totais, inicio=INICIO, fim=FIM):\n    """totais: {(distrito, date): atendimentos}. Devolve (linhas_mes, linhas_distrito)."""\n    dias = [inicio + timedelta(n) for n in range((fim - inicio).days + 1)]\n    distritos = sorted({d for d, _ in totais} | {CIDADE})\n    linhas_mes, linhas_distrito = [], []\n    for codigo in distritos:\n        if codigo == CIDADE:\n            por_dia = defaultdict(int)\n            for (c, d), v in totais.items():\n                por_dia[d] += v\n        else:\n            por_dia = {d: v for (c, d), v in totais.items() if c == codigo}\n        media_anual = sum(por_dia.get(d, 0) for d in dias) / len(dias)\n\n        por_mes, por_mes_ano, por_semana = defaultdict(list), defaultdict(list), defaultdict(list)\n        for d in dias:\n            v = por_dia.get(d, 0)\n            por_mes[d.month].append(v)\n            por_mes_ano[(d.month, d.year)].append(v)\n            por_semana[_semana(d)].append(v)\n\n        indices = []\n        for mes in range(1, 13):\n            media = sum(por_mes[mes]) / len(por_mes[mes])\n            indice = media / media_anual if media_anual else 0.0\n            indices.append(indice)\n            anos = {ano: sum(v) / len(v) for (m, ano), v in por_mes_ano.items() if m == mes}\n            calmo, intenso = min(anos, key=anos.get), max(anos, key=anos.get)\n            linhas_mes.append({"distrito_codigo": codigo, "distrito": nome_distrito(codigo) if codigo else "Recife",\n                               "mes": mes, "media_dia": round(media, 2), "indice": round(indice, 2),\n                               "ano_calmo": calmo, "media_ano_calmo": round(anos[calmo], 2),\n                               "ano_intenso": intenso, "media_ano_intenso": round(anos[intenso], 2)})\n\n        semanas = [sum(por_semana[w]) / len(por_semana[w]) for w in range(52)]\n        suave = [(semanas[w - 1] + semanas[w] + semanas[(w + 1) % 52]) / 3 for w in range(52)]\n        pico = max(range(52), key=lambda w: suave[w])\n        inicio_pico = date(2021, 1, 1) + timedelta(weeks=pico)\n        meses_criticos = periodo_critico(indices)\n        linhas_distrito.append({\n            "distrito_codigo": codigo, "distrito": nome_distrito(codigo) if codigo else "Recife",\n            "media_anual_dia": round(media_anual, 2),\n            "meses_criticos": meses_criticos, "periodo_critico": texto_periodo(meses_criticos),\n            "semana_pico": pico + 1,\n            "pico_texto": f"{inicio_pico:%d/%m} a {inicio_pico + timedelta(days=6):%d/%m}",\n            "media_semana_pico": round(suave[pico], 1),\n        })\n    return linhas_mes, linhas_distrito\n\n\ndef totais_da_defesa_civil(banco, inicio=INICIO, fim=FIM):\n    """{(distrito, date): reativos}, juntando a silver da Defesa Civil com o distrito de cada bairro."""\n    distrito_do_bairro = {b["chave"]: b.get("distrito_codigo")\n                          for b in banco["silver_bairros"].find({}, {"chave": 1, "distrito_codigo": 1})}\n    if not any(distrito_do_bairro.values()):\n        raise ValueError("silver_bairros sem distrito: rode antes python -m etl bairros (etapa 3a)")\n    totais = defaultdict(int)\n    for d in banco["silver_defesa_civil_bairro_dia"].find({}, {"data": 1, "bairro": 1, "reativos": 1}):\n        dia, distrito = d["data"].date(), distrito_do_bairro.get(d["bairro"])\n        if distrito and inicio <= dia <= fim and d.get("reativos"):\n            totais[(distrito, dia)] += d["reativos"]\n    return totais\n\n\ndef carregar(destino, avisar=print):\n    linhas_mes, linhas_distrito = calcular(totais_da_defesa_civil(destino.banco))\n    agora = datetime.now(timezone.utc)\n    for l in linhas_mes + linhas_distrito:\n        l["coletado_em"] = agora\n    destino.carregar(Carga("gold.calendario_risco_mes", linhas_mes, chaves=("distrito_codigo", "mes")))\n    destino.carregar(Carga("gold.calendario_risco_distrito", linhas_distrito, chaves=("distrito_codigo",)))\n    for l in linhas_distrito:\n        avisar(f"  {l[\'distrito\']:<8} período crítico: {l[\'periodo_critico\']:<22} "\n               f"pico: semana {l[\'semana_pico\']} ({l[\'pico_texto\']})  média {l[\'media_anual_dia\']}/dia")\n\n\nif __name__ == "__main__":\n    carregar(obter_destino())\n',
    'apps/fontes/repositorios/calendario.py': '"""Leitura do calendário de risco (gold, calculado por etl/derivados/calendario.py)."""\n\nfrom . import conexao\n\n\ndef por_mes():\n    return list(conexao.banco()["gold_calendario_risco_mes"].find({}, {"_id": 0}).sort([("distrito_codigo", 1), ("mes", 1)]))\n\n\ndef por_distrito():\n    return list(conexao.banco()["gold_calendario_risco_distrito"].find({}, {"_id": 0}).sort("distrito_codigo", 1))\n',
    'apps/painel/templates/painel/calendario.html': '{% extends \'components/app-shell.html\' %}\n\n{% block title %}Calendário de risco{% endblock %}\n{% block page_title %}Calendário de risco{% endblock %}\n\n{% block content %}\n<header class="mb-6 flex flex-wrap items-start justify-between gap-4 border-b border-slate-200 pb-5">\n  <div class="min-w-0">\n    <h1 class="text-2xl font-bold text-slate-900 md:text-3xl">Calendário de risco</h1>\n    <p class="mt-1 text-sm text-slate-500">Em que época do ano cada distrito mais precisa de equipe · atendimentos reativos da Defesa Civil, 2014–2024</p>\n  </div>\n  {% if linhas %}<a href="{% url \'calendario_csv\' %}" class="rounded-md border border-slate-300 px-3 py-1.5 text-xs font-semibold text-slate-700 hover:bg-slate-50">Baixar planilha</a>{% endif %}\n</header>\n\n{% if erro %}\n<p class="rounded-md bg-red-50 p-4 text-sm text-red-800">Não foi possível ler o calendário no banco.</p>\n{% elif not linhas %}\n<p class="rounded-md bg-slate-50 p-4 text-sm text-slate-600">Calendário ainda não calculado. Rode <code>python -m etl.derivados.calendario</code>.</p>\n{% else %}\n<section class="rounded-lg border border-slate-200 bg-white p-5 shadow-sm">\n  <h2 class="font-bold text-slate-900">Intensidade por mês</h2>\n  <p class="mb-4 text-xs text-slate-500">Número na célula: atendimentos por dia, em média. Cor: comparação com a média do próprio distrito (cada linha tem a sua escala). Passe o mouse para ver os anos mais calmo e mais intenso.</p>\n  <div class="overflow-x-auto">\n    <table class="w-full min-w-[760px] border-separate border-spacing-1 text-center text-xs">\n      <thead>\n        <tr><th class="text-left text-slate-500">Distrito</th>{% for m in meses %}<th class="font-semibold uppercase text-slate-500">{{ m }}</th>{% endfor %}</tr>\n      </thead>\n      <tbody>\n        {% for l in linhas %}\n        <tr>\n          <td class="whitespace-nowrap pr-2 text-left text-sm {% if forloop.first %}font-bold{% else %}font-semibold{% endif %} text-slate-900">{{ l.nome }}</td>\n          {% for c in l.celulas %}\n          <td title="{{ c.dica }}" class="rounded py-2 font-semibold\n            {% if c.tom == \'muito_alto\' %}bg-red-500 text-white{% elif c.tom == \'alto\' %}bg-orange-300 text-orange-950{% elif c.tom == \'acima\' %}bg-amber-100 text-amber-900{% elif c.tom == \'abaixo\' %}bg-sky-50 text-slate-600{% else %}bg-slate-50 text-slate-400{% endif %}">{{ c.media_dia|floatformat:0 }}</td>\n          {% endfor %}\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  <p class="mt-3 flex flex-wrap gap-3 text-[11px] text-slate-500">\n    <span><span class="inline-block size-3 rounded bg-red-500 align-middle"></span> 2× a média ou mais</span>\n    <span><span class="inline-block size-3 rounded bg-orange-300 align-middle"></span> 1,5× a 2×</span>\n    <span><span class="inline-block size-3 rounded bg-amber-100 align-middle"></span> acima da média</span>\n    <span><span class="inline-block size-3 rounded bg-sky-50 align-middle ring-1 ring-slate-200"></span> abaixo</span>\n    <span><span class="inline-block size-3 rounded bg-slate-50 align-middle ring-1 ring-slate-200"></span> bem abaixo</span>\n  </p>\n</section>\n\n<section class="mt-5 rounded-lg border border-slate-200 bg-white p-5 shadow-sm">\n  <h2 class="mb-4 font-bold text-slate-900">Resumo para o planejamento</h2>\n  <div class="overflow-x-auto">\n    <table class="w-full min-w-[620px] text-left text-sm">\n      <thead class="border-b border-slate-200 text-xs uppercase tracking-wide text-slate-500">\n        <tr><th class="py-2 pr-3">Distrito</th><th class="py-2 pr-3">Período crítico</th><th class="py-2 pr-3">Semana de pico</th><th class="py-2">Média no ano</th></tr>\n      </thead>\n      <tbody class="divide-y divide-slate-100">\n        {% for l in linhas %}\n        <tr>\n          <td class="py-2 pr-3 font-semibold text-slate-900">{{ l.nome }}</td>\n          <td class="py-2 pr-3 capitalize">{{ l.resumo.periodo_critico }}</td>\n          <td class="py-2 pr-3">{{ l.resumo.pico_texto }} <span class="text-xs text-slate-400">({{ l.resumo.media_semana_pico }}/dia)</span></td>\n          <td class="py-2">{{ l.resumo.media_anual_dia }} por dia</td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  <p class="mt-3 text-xs text-slate-500">Período crítico: meses seguidos com 50% ou mais acima da média do próprio distrito. Os "reativos" incluem colocação de lonas, que em parte pode ser preventiva.</p>\n</section>\n{% endif %}\n{% endblock %}\n',
    'tests/test_calendario.py': 'from datetime import date, timedelta\n\nimport pytest\n\nfrom apps.fontes.repositorios import conexao\nfrom etl.derivados import calendario as cal\n\nINICIO, FIM = date(2018, 1, 1), date(2019, 12, 31)\n\n\ndef _totais():\n    """DS VII: 2 por dia, e 10 por dia de abril a junho. DS VI: 1 por dia, sem estação."""\n    t = {}\n    d = INICIO\n    while d <= FIM:\n        t[(7, d)] = 10 if 4 <= d.month <= 6 else 2\n        t[(6, d)] = 1\n        d += timedelta(1)\n    return t\n\n\ndef test_periodo_critico_e_pico():\n    meses, distritos = cal.calcular(_totais(), INICIO, FIM)\n    r = {d["distrito_codigo"]: d for d in distritos}\n    assert r[7]["meses_criticos"] == [4, 5, 6] and r[7]["periodo_critico"] == "abril a junho"\n    assert 13 <= r[7]["semana_pico"] <= 27                                 # entre abril e junho\n    assert r[6]["periodo_critico"] == "sem período marcadamente acima da média"\n    assert r[0]["distrito"] == "Recife"                                      # a cidade inteira também entra\n    abril = next(m for m in meses if m["distrito_codigo"] == 7 and m["mes"] == 4)\n    assert abril["media_dia"] == 10 and abril["indice"] > 2\n\n\ndef test_periodo_que_atravessa_o_ano():\n    indices = [2, 2, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 2]\n    assert cal.periodo_critico(indices) == [12, 1, 2]\n    assert cal.texto_periodo([12, 1, 2]) == "dezembro a fevereiro"\n\n\n@pytest.mark.django_db\ndef test_tela_e_planilha(client, destino, monkeypatch):\n    meses, distritos = cal.calcular(_totais(), INICIO, FIM)\n    destino.banco["gold_calendario_risco_mes"].insert_many(meses)\n    destino.banco["gold_calendario_risco_distrito"].insert_many(distritos)\n    monkeypatch.setattr(conexao, "banco", lambda: destino.banco)\n    html = client.get("/calendario/").content.decode()\n    assert "abril a junho" in html and "DS VII" in html\n    linhas = client.get("/calendario/calendario.csv").content.decode("utf-8-sig").splitlines()\n    assert len(linhas) == 1 + 12 * 3                                         # Recife, DS VI e DS VII\n',
}
ANEXO_VIEWS = '\n\n\nMESES_CURTOS = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]\n\n\ndef _tom(indice):\n    """Cor da célula pelo índice (mês ÷ média do próprio distrito)."""\n    if indice >= 2:\n        return "muito_alto"\n    if indice >= 1.5:\n        return "alto"\n    if indice >= 1:\n        return "acima"\n    return "abaixo" if indice >= 0.6 else "baixo"\n\n\ndef calendario(request):\n    """Calendário de risco: em que meses cada distrito mais precisa de equipe."""\n    from apps.fontes.repositorios import calendario as repo_calendario\n    linhas, erro = [], False\n    try:\n        meses, resumos = repo_calendario.por_mes(), {r["distrito_codigo"]: r for r in repo_calendario.por_distrito()}\n        por_distrito = {}\n        for m in meses:\n            por_distrito.setdefault(m["distrito_codigo"], []).append({\n                **m, "tom": _tom(m["indice"]), "rotulo": MESES_CURTOS[m["mes"] - 1],\n                "dica": (f"{m[\'media_dia\']} atendimentos/dia em média ({m[\'indice\']}x a média do distrito). "\n                         f"Ano mais calmo: {m[\'ano_calmo\']} ({m[\'media_ano_calmo\']}/dia); "\n                         f"mais intenso: {m[\'ano_intenso\']} ({m[\'media_ano_intenso\']}/dia).")})\n        for codigo, celulas in sorted(por_distrito.items()):\n            linhas.append({"nome": celulas[0]["distrito"], "celulas": celulas, "resumo": resumos.get(codigo, {})})\n    except PyMongoError:\n        logger.exception("Falha ao ler o calendário de risco")\n        erro = True\n    return render(request, "painel/calendario.html", {"linhas": linhas, "meses": MESES_CURTOS, "erro": erro})\n\n\ndef calendario_csv(request):\n    from apps.fontes.repositorios import calendario as repo_calendario\n    resposta = HttpResponse(content_type="text/csv; charset=utf-8")\n    resposta["Content-Disposition"] = \'attachment; filename="calendario_risco.csv"\'\n    resposta.write("\\ufeff")\n    w = csv.writer(resposta, delimiter=";")\n    w.writerow(["Distrito", "Mês", "Atendimentos reativos por dia (média 2014-2024)", "Índice (mês / média do distrito)",\n                "Ano mais calmo", "Média no ano mais calmo", "Ano mais intenso", "Média no ano mais intenso"])\n    for m in repo_calendario.por_mes():\n        w.writerow([m["distrito"], m["mes"], m["media_dia"], m["indice"], m["ano_calmo"], m["media_ano_calmo"],\n                    m["ano_intenso"], m["media_ano_intenso"]])\n    return resposta\n\n'
BLOCO_NAV = '<a href="{% url \'calendario\' %}" class="flex h-11 items-center gap-3 rounded-md px-3 text-sm font-semibold transition-colors {% if current == \'calendario\' %}bg-slate-800 text-white{% else %}text-slate-400 hover:bg-slate-800 hover:text-white{% endif %}">\n  <i data-lucide="calendar-range" class="w-5 h-5"></i><span>Calendário</span>\n</a>\n'

def troca(p, velho, novo):
    s = Path(p).read_text(encoding='utf-8')
    if velho not in s:
        sys.exit(f'NAO ACHEI em {p}: {velho[:60]!r}')
    return s.replace(velho, novo, 1)

urls = troca('apps/painel/urls.py', '    path("dashboard/situacao.csv", views.situacao_csv, name="situacao_csv"),\n',
             '    path("dashboard/situacao.csv", views.situacao_csv, name="situacao_csv"),\n'
             '    path("calendario/", views.calendario, name="calendario"),\n'
             '    path("calendario/calendario.csv", views.calendario_csv, name="calendario_csv"),\n')
nav = troca('vigidesastre/templates/components/nav-links.html', '<a href="{% url \'relatorios\' %}"', BLOCO_NAV + '<a href="{% url \'relatorios\' %}"')
views = Path('apps/painel/views.py').read_text(encoding='utf-8').rstrip('\n') + ANEXO_VIEWS
for caminho, conteudo in NOVOS.items():
    Path(caminho).parent.mkdir(parents=True, exist_ok=True)
    Path(caminho).write_text(conteudo, encoding='utf-8')
Path('apps/painel/urls.py').write_text(urls, encoding='utf-8')
Path('vigidesastre/templates/components/nav-links.html').write_text(nav, encoding='utf-8')
Path('apps/painel/views.py').write_text(views, encoding='utf-8')
print("Etapa 4a aplicada. Agora: python -m pytest -q && python -m etl.derivados.calendario")
